"""Gate: views — a page stamped by the project's own generator is never edited by hand.

`views/current` rebuilds a page from records and compares. Some pages cannot be rebuilt on every
machine: their generator reads data that is not in the repository. Such a generator stamps the
page with a hash instead, on a line of its own:

    <!-- generated by scripts/costs.py --doc · sha256:<64 hex digits> -->

What is hashed, exactly: the page's text read as UTF-8, with each CRLF and each lone CR turned
into LF, split at LF, the one line that holds the stamp taken out, and the rest joined again with
LF. The SHA-256 of that text, encoded as UTF-8, is written in lower-case hex. So the stamp may sit on any line, and its
command can be read by a person; editing any other byte breaks the match. `stamp()` writes it.
"""

from __future__ import annotations

import hashlib
import re
from typing import TYPE_CHECKING

from themis import markdown
from themis.rule import Context, Param, proof, rule

if TYPE_CHECKING:
    from themis.proofs import World

#: A stamp: `generated by COMMAND · sha256:DIGEST`, anywhere on a line outside fenced code.
STAMP = re.compile(r"generated by (?P<command>\S.*?)\s+·\s+sha256:(?P<digest>[0-9a-fA-F]{64})(?![0-9a-fA-F])")

PAGES = Param("pages", [str], None, "larger",
              "the pages that may carry a stamp, as path patterns, such as docs/**/*.md")


def _lf(text: str) -> str:
    return re.sub(r"\r\n?", "\n", text)


def stamps(text: str) -> list[tuple[int, str, str]]:
    """(line number, command, digest) for each stamp outside fenced code."""
    found = []
    for number, line, code in markdown.lines_of(_lf(text)):
        if not code and (mark := STAMP.search(line)):
            found.append((number, mark["command"], mark["digest"].lower()))
    return found


def page_hash(text: str, line: int) -> str:
    """The hash a stamp on that line names: see the module's docstring for what goes in."""
    lines = _lf(text).split("\n")
    del lines[line - 1]
    return hashlib.sha256("\n".join(lines).encode("utf-8")).hexdigest()


def stamp(body: str, command: str) -> str:
    """The page a generator writes: its body, then the stamp as an HTML comment on the last line."""
    body = _lf(body)
    body = body if not body or body.endswith("\n") else body + "\n"
    digest = hashlib.sha256(body.encode("utf-8")).hexdigest()
    return f"{body}<!-- generated by {command} · sha256:{digest} -->\n"


@rule(
    "views/untouched",
    "A page stamped by its generator still hashes to the hash in its stamp.",
    params=(PAGES,),
    requires=("pages",),
    learned="A page built from data only one machine held was edited by hand, and no rerun elsewhere could tell.",
)
def untouched(ctx: Context) -> None:
    for name in sorted({name for pattern in ctx.param("pages") for name in ctx.files(pattern)}):
        text = ctx.read(name)
        if text is None:
            continue  # not text, so not a page a generator stamps
        found = stamps(text)
        if not found:
            continue
        ctx.inspect()
        if len(found) > 1:
            ctx.refuse(f"this page holds more than one stamp (lines {', '.join(str(row[0]) for row in found)})",
                       where=name, fix="a page carries one stamp; rerun its generator")
            continue
        line, command, digest = found[0]
        if page_hash(text, line) != digest:
            ctx.breach(f"the page no longer hashes to its stamp, so it was edited after `{command}` wrote it",
                       where=name, line=line, fix=f"run `{command}` again, and change the generator, not the page")


SETUP = '[rules."views/untouched"]\npages = ["docs/**/*.md"]\n'
TOOLS = "# Tools\n\n| Script | What it does |\n| --- | --- |\n| `scripts/build.sh` | Builds the site |\n"
COMMAND = "scripts/list_tools.py --doc"


def _project(world: World, page: str | bytes) -> None:
    """A plain docs-and-scripts project: a README, a script, and a page the script writes."""
    world.manifest(SETUP)
    world.write("README.md", "# A small project\n\nSee [the tools](docs/tools.md).\n")
    world.write("scripts/list_tools.py", "print('writes docs/tools.md from a folder only one machine has')\n")
    target = world.root / "docs/tools.md"
    target.parent.mkdir(parents=True, exist_ok=True)
    if isinstance(page, bytes):
        target.write_bytes(page)
    else:
        target.write_text(page, encoding="utf-8")


@proof("views/untouched", "a page as its generator wrote it", expect="pass")
def _(world: World) -> None:
    _project(world, stamp(TOOLS, COMMAND))
    world.write("docs/guide.md", "# A page written by hand, with no stamp\n")


@proof("views/untouched", "the stamp on the first line, and the page checked out with CRLF", expect="pass")
def _(world: World) -> None:
    last = stamp(TOOLS, COMMAND).rstrip("\n").rsplit("\n", 1)[1]
    _project(world, (last + "\n" + TOOLS).replace("\n", "\r\n").encode("utf-8"))


@proof("views/untouched", "a stamp quoted in fenced code is not a stamp", expect="pass")
def _(world: World) -> None:
    quoted = "```\n" + stamp("other\n", "x").rsplit("\n", 2)[1] + "\n```\n"
    _project(world, stamp(TOOLS + quoted, COMMAND))


@proof("views/untouched", "a cell edited by hand", expect="fail", contains="no longer hashes to its stamp")
def _(world: World) -> None:
    _project(world, stamp(TOOLS, COMMAND).replace("Builds the site", "Builds and ships the site"))


@proof("views/untouched", "a line added under the stamp", expect="fail", contains="edited after `scripts/list_tools.py")
def _(world: World) -> None:
    _project(world, stamp(TOOLS, COMMAND) + "A note typed later.\n")


@proof("views/untouched", "two stamps on one page", expect="refuse", contains="more than one stamp")
def _(world: World) -> None:
    _project(world, stamp(stamp(TOOLS, COMMAND), COMMAND))


@proof("views/untouched", "no page in scope carries a stamp", expect="refuse", contains="nothing was inspected")
def _(world: World) -> None:
    _project(world, TOOLS)
